import os
import sys

import six

from .aatrace_collector import AatraceCollector, Status, observer_callbacks
from .emil_parser import EmilParser
from .exceptions import (
    AaTracingAlreadyStarted,
    AaTracingNotRunning,
    CallbackAlreadyRegistered,
    ObserverTimeout,
)
from .logger_config import log
from .sack_downloader_best_match import SackDownloaderBestMatch


class ta_emil_parser(object):
    ROBOT_LIBRARY_SCOPE = "GLOBAL"
    ROBOT_LISTENER_API_VERSION = 2

    def __new__(cls, *args, **kwargs):
        if not hasattr(cls, "_instance"):
            cls._instance = super(ta_emil_parser, cls).__new__(cls)
        return cls._instance

    def __init__(self, emil_messages_definition=None, load_definition_at_init=True):
        """
        Library that helps to parse, disp and collect aatrace messages (SIC protocol messages) between
        internal eNB components.

        :param emil_messages_definition: string or path to EMIL IDA SACK 'types.dat' file. If not provided will try to download this file.
        :param load_definition_at_init: If False - will not load messaged definition on library init - use method load_emil_message_definition.
        :returns: None.
        """
        self.ROBOT_LIBRARY_LISTENER = self
        self.parser = EmilParser(messages_definition=None)
        if str(load_definition_at_init) == "True":
            self.load_emil_message_definition(emil_messages_definition)
        self.aatrace_collector = None
        self.message_structures = {}

    def load_emil_message_definition(self, emil_messages_definition=None):
        """
        Will try to load aatrace messages definitions into parser. emil_messages_definition can be:
        1) None - will try to load EMIL IDA SACK, unzip it and read file 'types.dat' to get definitions.
        2) Path to local file containing messages definitions (usualy 'types.dat' from EMIL IDA SACK.
        3) String containing messages definitions (alread read file 'types.dat' content).

        :param emil_messages_definition: None, path to file or string with messages definitions.
        """
        if emil_messages_definition and os.path.isfile(emil_messages_definition):
            self.parser.load_messages_definition(
                self._read_definition_file(emil_messages_definition)
            )
            log.debug(
                "EmilParser loaded with definitions from file: '{}'".format(
                    emil_messages_definition
                )
            )
        elif isinstance(emil_messages_definition, str):
            self.parser.load_messages_definition(emil_messages_definition)
            log.debug("EmilParser loaded with definitions from string")
        else:
            sack_downloader = SackDownloaderBestMatch()
            path_to_definitions = sack_downloader.get_types_dat_file()
            self.parser.load_messages_definition(
                self._read_definition_file(path_to_definitions)
            )
            log.debug("EmilParser loaded by downloading sack file")

    def create_message_structure(self, from_name=None, from_hex_id=None):
        """
        Creates a tree-like strucutre of message identified by name/hex_id.

        Robot Framework example::

            Library      ta_emil_parser    emil_messages_definition=types.dat
            ...
            ${msg_structure}=    Create message structure    from_name=RROM_CELL_FREQ_CHANGE_REQ_MSG
            Log    ${msg_structure}

        Will output something like::

            RROM_CELL_FREQ_CHANGE_REQ_MSG
            |-- msgHeader
            |   |-- flags
            |   |   |-- system
            |   |   +-- user
            |   |-- id
            |   |-- length
            |   |-- receiver
            |   |   |-- board
            |   |   |-- cpu
            |   |   +-- task
            |   +-- sender
            |       |-- board
            |       |-- cpu
            |       +-- task
            |-- numOfLaaSelectedCells
            |-- selectedCells
            |   |-- board
            |   |-- cpu
            |   |-- flags
            |   |   |-- system
            |   |   +-- user
            |   |-- id
            |   |-- length
            |   |-- msgHeader
            |   |   |-- flags
            |   |   |   |-- system
            |   |   |   +-- user
            |   |   |-- id
            |   |   |-- length
            |   |   |-- receiver
            |   |   |   |-- board
            |   |   |   |-- cpu
            |   |   |   +-- task
            |   |   +-- sender
            |   |       |-- board
            |   |       |-- cpu
            |   |       +-- task
            |   |-- receiver
            |   |   |-- board
            |   |   |-- cpu
            |   |   +-- task
            |   |-- sender
            |   |   |-- board
            |   |   |-- cpu
            |   |   +-- task
            |   |-- spare
            |   |-- system
            |   |-- task
            |   +-- user
            +-- selectedCells
                |-- earfcnDL
                +-- eutraCellId

        :param from_name: Name of message structure to be created.
        :type from_name: str
        :param from_hex_id: Hex id of message to be created.
        :type from_hex_id: str
        :returns: **ta_emil_parser.emil_parser.AaTraceMessage** object
        """
        if from_name:
            if from_name in self.message_structures.keys():
                return self.message_structures[from_name]
            message_structure = self.parser.create_message_structure_from_definition(
                msg_name=from_name
            )
        else:
            from_name = self.get_message_name_from_hex_id(from_hex_id)
            if from_name in self.message_structures.keys():
                return self.message_structures[from_name]
            message_structure = self.parser.create_message_structure_from_definition(
                hex_id=from_hex_id
            )

        self.message_structures[from_name] = message_structure
        return message_structure

    def create_message_from_bytes(self, bytes):
        """
        Creates a dict-type parsed (filled) message when provided bytes of SIC protocol.

        Robot Framework example::

            Library      ta_emil_parser
            ...
            ${message}=    Create message from bytes    bytes=00004eca201b0f00201115e50014000412000000
            Log    ${message}

        Will output something like::

            Message(
            {'RROM_LEAP_SECONDS_UPDATE_IND_MSG': {'leapSeconds': '12000000',
                                                  'msgHeader': {'flags': {'system': '00',
                                                                          'user': '04'},
                                                                'id': '00004eca',
                                                                'length': '0014',
                                                                'receiver': {'board': '20',
                                                                             'cpu': '1b',
                                                                             'task': '0f00'},
                                                                'sender': {'board': '20',
                                                                           'cpu': '11',
                                                                           'task': '15e5'}}}})

        :param bytes: String of aatrace SIC message bytes.
        :type bytes: str
        :returns: **ute_common_abstract_core.message.Message** dict-type object.
        """
        msg_name = self.parser.get_message_name_from_bytes(bytes)
        if msg_name not in self.message_structures.keys():
            message_structure = self.parser.create_message_structure_from_definition(
                msg_name=msg_name
            )
            self.message_structures[msg_name] = message_structure
        else:
            message_structure = self.message_structures[msg_name]
        message = message_structure.parse(bytes)
        return message

    def get_message_name_from_hex_id(self, hex_id):
        """
        Converts message hex id into message name.

        Robot Framework example::

            Library      ta_emil_parser    emil_messages_definition=types.dat
            ...
            ${msg_name}=     Get message name from hex_id    hex_id=221D
            Log    ${msg_name}

        Will output::

            MAC_USER_DELETE_RESP_MSG

        :param hex_id: hex id of message from sack types.dat file.
        :type hex_id: str
        :returns: message name as string corresponding to hex id.
        """
        return self.parser.get_message_name_from_hex_id(hex_id)

    def get_message_hex_id_from_name(self, msg_name):
        """
        Convers message name into message hex id.

        Robot Framework example::

            Library      ta_emil_parser
            ...
            ${msg_hex_id}=   Get message hex id from name    msg_name=ENBC_L3_SIGN_CONN_SETUP_RESP_MSG
            Log    ${msg_hex_id}

        Will output::

            4588

        :param msg_name: message name from sack types.dat file.
        :type msg_name: str
        :returns: hex id as string of corresponding message name.
        """
        return self.parser.get_message_hex_id_from_name(msg_name)

    def start_aatrace_for(self, messages, nodes=None):
        """
        Starts aatrace message collection. Connects to eNB, sends which messages to trace and continously reads output.
        Should be called only once per test. Takes a list of messages names and/or hex ids to trace.
        If message definitions were loaded (during library init or using 'load_emil_message_definition' method,
        parameter 'messages' can contain both: messages names and/or messages hex ids.
        If message definitions were not loaded, 'messages' can contain ONLY message hex ids or exception will be raised.

        'nodes' is an optional parameter that can be:
        - empty (None). If not specified, there are default nodes that will be used. Created based on fsm hardware config.
        - a list of nodes names found in /home/ute/btslog2/nodes.ini file. Messages will be collected from those nodes.
        - a dict in format::

            {'NODE_NAME_1': {'Board': 'XX', 'CPU': 'YY'},
             'NODE_NAME_2': {'Board': 'XX', 'CPU': 'YY', 'MsgTask': 'ZZZZ'}}

        Robot Framework example::

            Library      ta_emil_parser    emil_messages_definition=test/resources/types.dat
            ...
            Start aatrace for    messages=TUP_L3_CONN_SETUP_REQ_MSG, 42AC, 0x802A    nodes=FSMr2_FSM_1_FSP_1_CHIP_1_CPU_2

            Library      ta_emil_parser    load_definition_at_init=False
            ...
            Start aatrace for    messages=42AC, 0x802A

        :param messages: List or coma/space-delimited string of message names which will be traced.
        :type messages: list
        :param nodes: List of nodes (section names) from btslog nodes.ini file, None or dict.
        :type nodes: None, list, dict
        :raises: **ta_emil_parser.exceptions.AaTracingAlreadyStarted** when called second time.
        :raises: ValueError if message definitions were not loaded and parameter 'messages' contains not only hex ids.
        """
        msg_list = _convert_to_list_if_string_or_return_as_is(messages)
        message_hex_id_list = []

        for msg_id in msg_list:
            msg_hex_id = self._get_message_hex_id_or_raise_if_message_definition_not_loaded_and_msg_id_is_not_hex(
                msg_id
            )
            if self.parser.is_messages_definition_loaded():
                self.create_message_structure(from_hex_id=msg_hex_id)
            message_hex_id_list.append(msg_hex_id)

        nodes = _convert_to_list_if_string_or_return_as_is(nodes)
        if (not self.aatrace_collector) or (
            not self.aatrace_collector.is_running.is_set()
        ):
            self.aatrace_collector = AatraceCollector(
                self.parser, message_hex_id_list, nodes
            )
        else:
            raise AaTracingAlreadyStarted("Cant start.")
        log.debug("AatraceCollector instance created. Thread running.")

    def stop_aatrace(self):
        """
        Stops aatrace collection - disconects from eNB and stops all observers.
        In Robot Framework does not have to be used - collecting stops automaticaly at test end.

        Robot Framework example::

            Library      ta_emil_parser    emil_messages_definition=test/resources/types.dat
            ...
            Start aatrace for    messages=TUP_L3_CONN_SETUP_REQ_MSG, FAULT_ACK_MSG, MAC_USER_DELETE_REQ_MSG
            ...
            [Teardown]    Stop aatrace
        """
        log.debug("Stopping AatraceCollector.")
        if self.aatrace_collector and self.aatrace_collector.is_running.is_set():
            self.aatrace_collector.stop()
            self.aatrace_collector.thread.join()

    def observe_aatrace_message(
        self,
        msg_id,
        occurrence=1,
        timeout=10,
        on_success=None,
        on_timeout=None,
        on_each_occurrence=None,
    ):
        """
        Runs in background - is NOT blocking.
        Creates and starts observer for message for which aatrace collection is already running.
        When number of occurrences or timeout is reached silently stops observer - does not raise anything.
        If message definition is not loaded already (during library init or with 'load_emil_message_definition' method and parameter
        'msg_id' is message name instead of message hex id raises ValueError.

        Robot Framework usage::

            Library      ta_emil_parser    emil_messages_definition=test/resources/types.dat
            ...
            Start aatrace for    messages=42AC, 0x802A, ENBC_L3_SIGN_CONN_SETUP_REQ_MSG
            ...
            Observe aatrace message    msg_id=ENBC_L3_SIGN_CONN_SETUP_REQ_MSG    occurrence=5    timeout=12
            Observe aatrace message    msg_id=42AC                               occurrence=2    timeout=10
            Observe aatrace message    msg_id=0x802A                             occurrence=2    timeout=10

        :param msg_id: Name or hex id of message that aatrace is started for (using **Start aatrace for** keyword)
        :type msg_id: str
        :param occurrence: Number of messages after which observer stops and changes status to SUCCESS.
        :type occurrence: int
        :param timeout: Number of seconds that observer will run. After this time observer is stopped and its status is TIMEOUT.
        :type timeout: int
        :param on_success: Callback function (when calling thru Python) OR callback function name (string) marked
                           with 'emil_observer_callback' decorator, to be called when observer finishes with status SUCCESS.
        :type on_success: function OR str
        :param on_timeout: Callback function (when calling thru Python) OR callback function name (string) marked
                           with 'emil_observer_callback' decorator, to be called when observer finishes with status TIMEOUT.
        :type on_timeout: function OR str
        :param on_each_occurrence: Callback function (when calling thru Python) OR callback function name (string) marked
                                   with 'emil_observer_callback' decorator, to be called on each message occurrence.
        :type on_each_occurrence: function OR str
        :raises: ValueError if message definitions were not loaded and parameter 'msg_id' is not hex id.
        :returns: instance of aatrace_collector.MessageObserver class
        """
        self._raise_if_aatrace_collector_is_not_running()
        msg_hex_id = self._get_message_hex_id_or_raise_if_message_definition_not_loaded_and_msg_id_is_not_hex(
            msg_id
        )
        return self.aatrace_collector.create_observer(
            msg_hex_id,
            occurrence=int(occurrence),
            timeout=float(timeout),
            on_success=on_success,
            on_timeout=on_timeout,
            on_each_occurrence=on_each_occurrence,
        )

    def wait_for_aatrace_message(
        self,
        msg_id,
        occurrence=1,
        timeout=10,
        on_success=None,
        on_timeout=None,
        on_each_occurrence=None,
    ):
        """
        Runs in foreground - IS blocking.
        Waits (blocks) for already started observer (started with **Observe aatrace message** keyword) to finish.
        In this 'mode' other input parameters are not taken into use.
        If observer status is SUCCESS - returns observer object.
        If observer status is TIMEOUT - raises **ta_emil_parser.exceptions.ObserverTimeout** exception.

        When **Observe aatrace message** keyword was not used and this keyword is used instead, starts observer and
        waits (blocks) until observer finishes. Other parameters are taken into use.

        If message definition is not loaded already (during library init or with 'load_emil_message_definition' method and parameter
        'msg_id' is message name instead of message hex id raises ValueError.

        Robot Framework example 1::

            Library      ta_emil_parser
            Library      ta_egate_cmd_parser
            ...
            Start aatrace for    messages=TUP_LINK_STATE_IND_MSG, 0x802A
            ...
            Observe aatrace message    msg_id=MAC_USER_SETUP_RESP_MSG    occurrence=1    timeout=15
            Run command    attach_ue    id=1
            Wait for aatrace message    msg_id=0x802A
            Log    This will not be executed until observer is finished

        Robot Framework example 2::

            Library      ta_emil_parser    load_definition_at_init=False
            ...
            Start aatrace for    messages=42AC
            ...
            Wait for aatrace message    msg_id=42AC    occurrence=3    timeout=8
            Log    This will not be executed until observer is finished

        :param msg_id: Name or hex id of message that aatrace is started for (using **Start aatrace for** keyword)
        :type msg_id: str
        :param occurrence: Number of messages after which observer stops and changes status to SUCCESS.
        :type occurrence: int
        :param timeout: Number of seconds that observer will run. After this time observer is stopped and its status is TIMEOUT.
        :type timeout: int
        :param on_success: Callback function (when calling thru Python) OR callback function name (string) marked
                           with 'emil_observer_callback' decorator, to be called when observer finishes with status SUCCESS.
        :type on_success: function OR str
        :param on_timeout: Callback function (when calling thru Python) OR callback function name (string) marked
                           with 'emil_observer_callback' decorator, to be called when observer finishes with status TIMEOUT.
        :type on_timeout: function OR str
        :param on_each_occurrence: Callback function (when calling thru Python) OR callback function name (string) marked
                                   with 'emil_observer_callback' decorator, to be called on each message occurrence.
        :type on_each_occurrence: function OR str
        :returns: If awaited observer status is SUCCESS returns observer object.
        :raises: raises **ta_emil_parser.exceptions.ObserverTimeout** exception if observer status is TIMEOUT.
        :raises: ValueError if message definitions were not loaded and parameter 'msg_id' is not hex id.
        """
        self._raise_if_aatrace_collector_is_not_running()
        msg_hex_id = self._get_message_hex_id_or_raise_if_message_definition_not_loaded_and_msg_id_is_not_hex(
            msg_id
        )
        try:
            msg_observer = self.aatrace_collector.subscribed_observers[msg_hex_id]
        except KeyError:
            msg_observer = self.aatrace_collector.create_observer(
                msg_hex_id,
                occurrence=int(occurrence),
                timeout=float(timeout),
                on_success=on_success,
                on_timeout=on_timeout,
                on_each_occurrence=on_each_occurrence,
            )

        msg_observer.await_finish()

        if msg_observer.status == Status.SUCCESS:
            self.aatrace_collector.unsubscribe_observer(msg_observer)
            return msg_observer
        elif msg_observer.status == Status.TIMEOUT:
            self.aatrace_collector.unsubscribe_observer(msg_observer)
            raise ObserverTimeout("For message: %s" % msg_observer.name)
        else:
            self.stop_aatrace()
            raise Exception(
                "Wrong status for observer %s: %s"
                % (msg_observer.name, msg_observer.status)
            )

    def get_parsed_aatrace_message(
        self,
        msg_id,
        occurrence=-1,
        timeout=10,
        on_success=None,
        on_timeout=None,
        on_each_occurrence=None,
    ):
        """
        Runs in foreground - IS blocking.
        Waits (blocks) for already started observer (started with **Observe aatrace message** keyword) to finish and
        returns Xth (occurrence) parsed message as dict-like structure.
        If used on already finished (status SUCCESS) observer, immediately returns Xth (occurrence) parsed message as dict-like structure.

        When **Observe aatrace message** or **Wait for aatrace message** keyword was not used and this keyword is used instead,
        starts observer and waits (blocks) until observer finishes and returns Xth (occurrence) parsed message as dict-like structure.

        This keyword will NOT start new observer if one for the same message is already finished!

        If message definition is not loaded already (during library init or with 'load_emil_message_definition' method and parameter
        'msg_id' is message name instead of message hex id raises ValueError.

        Robot Framework usage 1::

            Library      ta_emil_parser
            Library      ta_egate_cmd_parser
            ...
            Start aatrace for    messages=MAC_USER_SETUP_RESP_MSG, FAULT_ACK_MSG
            ...
            Observe aatrace message    msg_id=MAC_USER_SETUP_RESP_MSG    occurrence=2    timeout=15
            Run command    attach_ue    id=1
            Run command    attach_ue    id=2
            ${2nd_msg}=    Get parsed aatrace message    msg_id=MAC_USER_SETUP_RESP_MSG    occurrence=2
            Log    This will not be executed until observer is finished
            Log    ${2nd_msg}

        Will output::

            Message(
            {'FAULT_ACK_MSG': {'faultId': 'd0070000',
                   'faultState': '00000000',
                   'msgHeader': {'flags': {'system': '00', 'user': '04'},
                                 'id': '00008018',
                                 'length': '0018',
                                 'receiver': {'board': '22',
                                              'cpu': '3d',
                                              'task': '1202'},
                                 'sender': {'board': '20',
                                            'cpu': '11',
                                            'task': '15ea'}}}})

        Robot Framework usage 2::

            Library      ta_emil_parser
            ...
            Start aatrace for    messages=TUP_LINK_STATE_IND_MSG, FAULT_ACK_MSG
            ...
            Observe aatrace message    msg_id=FAULT_ACK_MSG    occurrence=4    timeout=12
            ...
            ${2nd_msg}=    Get parsed aatrace message    msg_id=FAULT_ACK_MSG
            Log    ${2nd_msg}

        Robot Framework usage 3::

            Library      ta_emil_parser    load_definition_at_init=False
            ...
            Start aatrace for    messages=0x802A, 42AC
            ...
            ${2nd_msg}=    Get parsed aatrace message    msg_id=42AC    occurrence=2    timeout=12
            Log    ${2nd_msg}

        :param msg_id: Name or hex id of message that aatrace is started for (using **Start aatrace for** keyword)
        :type msg_id: str
        :param occurrence: Number of messages after which observer stops and changes status to SUCCESS.
        :type occurrence: int
        :param timeout: Number of seconds that observer will run. After this time observer is stopped and its status is TIMEOUT.
        :type timeout: int
        :param on_success: Callback function (when calling thru Python) OR callback function name (string) marked
                           with 'emil_observer_callback' decorator, to be called when observer finishes with status SUCCESS.
        :type on_success: function OR str
        :param on_timeout: Callback function (when calling thru Python) OR callback function name (string) marked
                           with 'emil_observer_callback' decorator, to be called when observer finishes with status TIMEOUT.
        :type on_timeout: function OR str
        :param on_each_occurrence: Callback function (when calling thru Python) OR callback function name (string) marked
                                   with 'emil_observer_callback' decorator, to be called on each message occurrence.
        :type on_each_occurrence: function OR str
        :returns: If awaited observer status is SUCCESS returns parsed dict-like message of type **ute_common_abstract_core.message.Message**.
        :raises: raises **ta_emil_parser.exceptions.ObserverTimeout** exception if observer status is TIMEOUT.
        :raises: ValueError if message definitions were not loaded and parameter 'msg_id' is not hex id.
        """
        self._raise_if_aatrace_collector_is_not_running()
        msg_hex_id = self._get_message_hex_id_or_raise_if_message_definition_not_loaded_and_msg_id_is_not_hex(
            msg_id
        )
        msg_observer = self.wait_for_aatrace_message(
            msg_hex_id,
            occurrence=abs(int(occurrence)),
            timeout=float(timeout),
            on_success=on_success,
            on_timeout=on_timeout,
            on_each_occurrence=on_each_occurrence,
        )
        msg_bytes = msg_observer.get_message(
            int(occurrence) if int(occurrence) < 0 else int(occurrence) - 1
        )
        return self.create_message_from_bytes(msg_bytes)

    def _raise_if_aatrace_collector_is_not_running(self):
        if (not self.aatrace_collector) or (
            not self.aatrace_collector.is_running.is_set()
        ):
            raise AaTracingNotRunning("Not started or already stopped.")

    def _read_definition_file(self, path_to_file):
        if sys.version_info[0] >= 3:
            mode = "rb"
        else:
            mode = "r"
        # if above does not work, must use encoding= 'unicode_escape'
        with open(path_to_file, mode=mode) as def_file:
            messages_defs = def_file.read()
        if sys.version_info[0] >= 3:
            out = messages_defs.decode(errors="replace")
        else:
            out = messages_defs
        return out

    def _get_message_hex_id_or_raise_if_message_definition_not_loaded_and_msg_id_is_not_hex(
        self, msg_id
    ):
        if self.parser.is_messages_definition_loaded():
            if _is_hex_number(msg_id):
                return _format_hex_number_to_msg_hex_id(msg_id)
            else:
                return self.get_message_hex_id_from_name(msg_id)
        else:
            if _is_hex_number(msg_id):
                return _format_hex_number_to_msg_hex_id(msg_id)
        self.stop_aatrace()
        raise ValueError(
            "Message definition not loaded, so message '{}' should be identified by hex id".format(
                msg_id
            )
        )

    def _end_test(self, name, attr):
        self.stop_aatrace()


def emil_observer_callback(func):
    """
    USE THIS DECORATOR WHEN 'Observe aatrace message', 'Wait for aatrace message' or 'Get parsed aatrace message' are called thru
    Robot Framework, like in a below case. When calling 'observe_aatrace_message', 'wait_for_aatrace_message' or 'get_parsed_aatrace_message'
    directly from Python, their arguments - 'on_success', 'on_timeout', 'on_each_occurrence' can just take callback function itself
    and this decorator does not have to be used!

    Use as decorator! Registers given function as candidate for callback to emil observers.
    if registered function is to be used 'on_timeout' or 'on_success' it should not have arguments (except self, if its a method).
    if registered function is to be used 'on_each_occurrence' it should take one argument (or two if it is a method).

    Usage from Python (file callbacks.py)::

        from ta_emil_parser.interface import emil_observer_callback

        @emil_observer_callback
        def callback_function(msg_bytes):
            print(msg_bytes)

    Usage from Robot::

        *** Settings ***
        Library    ta_emil_parser
        Library    callbacks

        *** Test Cases ***
        Some test case
            Start aatrace for    messages=FAULT_ACK_MSG
            Observe aatrace message    msg_name=FAULT_ACK_MSG    occurrence=5    timeout=12   on_each_occurrence=callback_function
    """
    f_name = func.__name__
    if f_name in observer_callbacks.keys():
        raise CallbackAlreadyRegistered(f_name)
    observer_callbacks[f_name] = func


def _convert_to_list_if_string_or_return_as_is(to_convert):
    if isinstance(to_convert, six.string_types):
        to_convert = str(to_convert)
        to_convert = to_convert.replace(",", " ").split(" ")
        to_convert = [x for x in to_convert if bool(x)]
        return to_convert
    return to_convert


def _is_hex_number(value):
    try:
        int(value, 16)
        return True
    except ValueError:
        return False


def _format_hex_number_to_msg_hex_id(hex_num):
    return "{:04X}".format(int(hex_num, 16))
